import { TokenSearchField } from '@kerfjs/ui/token-search-field';

type Token = { id: string; label: string; value: string };
export function mountSearch(target: HTMLElement, app: { query: string; tokens: Token[]; parse(query: string): void; suggest(query: string): void; replaceToken(id: string, value: string): void; removeToken(id: string): void; clear(): void; restoreCaret(): void }) {
  return TokenSearchField({
    target,
    label: 'Search tasks',
    value: app.query,
    tokens: app.tokens,
    onInput: (query: string) => { app.parse(query); app.suggest(query); },
    onTokenRemove: (id: string) => { app.removeToken(id); app.restoreCaret(); },
    onTokenReplace: (id: string, value: string) => { app.replaceToken(id, value); app.restoreCaret(); },
    onClear: () => { app.clear(); app.restoreCaret(); }
  });
}
